136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
139	        // Idempotent create: when the request carries an 'Idempotency-Key' already seen, return the
140	        // owner originally created for that key with 200, instead of creating a duplicate.
141	        String idempotencyKey = currentIdempotencyKey();
142	        if (idempotencyKey != null) {
143	            Integer existingId = idempotentCreates.get(idempotencyKey);
144	            if (existingId != null) {
145	                Owner existing = this.clinicService.findOwnerById(existingId);
146	                if (existing != null) {
147	                    OwnerDto existingDto = ownerMapper.toOwnerDto(existing);
148	                    existingDto.setBulkSignupWarning(isBulkSignupWarning());
149	                    return new ResponseEntity<>(existingDto, HttpStatus.OK);
150	                }
151	            }
152	        }
153	        // Prefer the structured address fields when present; the flat 'address' input remains accepted
154	        // for backward compatibility. When structured, the stored/returned address is the composed
155	        // normalized addressLine1 (with a single space and the normalized addressLine2 appended when
156	        // addressLine2 is present); otherwise it is the normalized flat 'address'.
157	        boolean structured = !isBlank(ownerFieldsDto.getAddressLine1());
158	        String addressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
159	        String addressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
160	        String address;
161	        if (structured) {
162	            address = addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2;
163	        } else {
164	            address = normalizeAddress(ownerFieldsDto.getAddress());
165	        }
166	        List<String> missingFields = new ArrayList<>();
167	        if (isBlank(ownerFieldsDto.getFirstName())) {
168	            missingFields.add("firstName");
169	        }
170	        if (isBlank(ownerFieldsDto.getLastName())) {
171	            missingFields.add("lastName");
172	        }
173	        if (isBlank(address)) {
174	            missingFields.add("address");
175	        }
176	        if (isBlank(ownerFieldsDto.getCity())) {
177	            missingFields.add("city");
178	        }
179	        if (isBlank(ownerFieldsDto.getTelephone())) {
180	            missingFields.add("telephone");
181	        }
182	        if (!missingFields.isEmpty()) {
183	            throw new MissingOwnerFieldsException(missingFields);
184	        }
185	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
186	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
187	        HttpHeaders headers = new HttpHeaders();
188	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
189	        owner.setAddress(address);
190	        owner.setAddressLine1(structured ? addressLine1 : null);
191	        owner.setAddressLine2(structured && !addressLine2.isEmpty() ? addressLine2 : null);
192	        owner.setTelephone(telephone);
193	        validateEmailDomain(owner.getEmail());
194	        validatePostcode(owner.getPostcode(), owner.getRegion());
195	        // The household is keyed deterministically on (lastName, postcode): every owner receives the
196	        // same stable householdId as anyone sharing its normalized last name and postcode, without any
197	        // explicit link. This computed value drives duplicate detection and the household size.
198	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
199	        // A new owner may join an existing household (same computed householdId); rather than being
200	        // rejected, the joiner is admitted with a capped membership level (see below).
201	        // Remaining duplicate detection is consolidated into the single derived identity key: a create
202	        // is rejected when the new owner's whole identity key equals an existing owner's.
203	        if (isIdentityKeyInUse(owner.getIdentityKey())) {
204	            throw new DuplicateIdentityException(owner.getIdentityKey());
205	        }
206	        if (isCityAtCapacity(owner.getCity())) {
207	            throw new CityAtCapacityException(owner.getCity());
208	        }
209	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
210	            throw new FutureRegistrationDateException(owner.getRegistrationDate());
211	        }
212	        LocalDate effectiveDate = owner.getRegistrationDate() != null
213	            ? owner.getRegistrationDate() : LocalDate.now();
214	        LocalDate registrationDate = toBusinessDay(effectiveDate);
215	        if (isDailyRegistrationLimitReached(registrationDate)) {
216	            throw new DailyRegistrationLimitException(registrationDate);
217	        }
218	        owner.setRegistrationDate(registrationDate);
219	        owner.setCustomerCode(deduplicateCustomerCode(customerCodeFor(owner)));
220	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
221	        owner.setHouseholdSize(householdSizeAfterCreate(owner.getHouseholdId()));
222	        owner.setMembershipLevel(cappedMembershipLevel(owner));
223	        // A declared household member (one that set 'sharesHousehold' to join an existing household) is
224	        // not a suspected duplicate; otherwise fall back to the soft last-name + postcode match.
225	        Integer possibleDuplicateOf = sharesHousehold ? null : possibleDuplicateOf(owner);
226	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
227	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
228	        this.clinicService.saveOwner(owner);
229	        if (idempotencyKey != null) {
230	            idempotentCreates.put(idempotencyKey, owner.getId());
231	        }
232	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
233	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
234	            owner.getMembershipNumber());
235	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
236	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
237	        headers.setLocation(UriComponentsBuilder.newInstance()
238	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
239	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
240	    }
