242	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
243	    @Override
244	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
245	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
246	        if (currentOwner == null) {
247	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
248	        }
249	        currentOwner.setAddress(ownerFieldsDto.getAddress());
250	        currentOwner.setCity(ownerFieldsDto.getCity());
251	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
252	        currentOwner.setLastName(ownerFieldsDto.getLastName());
253	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
254	        this.clinicService.saveOwner(currentOwner);
255	        OwnerDto ownerDto = ownerMapper.toOwnerDto(currentOwner);
256	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
257	        return new ResponseEntity<>(ownerDto, HttpStatus.NO_CONTENT);
258	    }
