260	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
261	    @Transactional
262	    @Override
263	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
264	        Owner owner = this.clinicService.findOwnerById(ownerId);
265	        if (owner == null) {
266	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
267	        }
268	        // Soft delete: retain the row, flag it deleted. The owner remains readable via GET, but
269	        // duplicate/identity detection on create ignores owners flagged deleted.
270	        owner.setDeleted(true);
271	        this.clinicService.saveOwner(owner);
272	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
273	    }
