340	    private static boolean isBlank(String value) {
341	        return value == null || value.isBlank();
342	    }
343	
344	    /**
345	     * Reads the {@code Idempotency-Key} header from the current request, or {@code null} when the
346	     * header is absent, blank, or there is no bound request. A present, non-blank value is trimmed.
347	     *
348	     * @return the trimmed idempotency key, or {@code null} when none was supplied
349	     */
350	    private static String currentIdempotencyKey() {
351	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
352	        if (!(attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttributes)) {
353	            return null;
354	        }
355	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
356	        return isBlank(key) ? null : key.trim();
357	    }
