359	    /**
360	     * The set of disposable email domains that owners may not register with. Compared
361	     * case-insensitively against the domain part of the supplied email.
362	     */
363	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
364	        "mailinator.com", "tempmail.com", "guerrillamail.com");
365	
366	    /**
367	     * Rejects an owner whose email domain is on the disposable-domain blocklist
368	     * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Email is optional:
369	     * a {@code null} or blank value, or one without an {@code '@'} domain part, is accepted here (the
370	     * {@code @Email} Bean Validation constraint governs format). The domain is compared
371	     * case-insensitively; the stored email is already lower-cased.
372	     *
373	     * @param email the owner's email (may be {@code null})
374	     * @throws DisposableEmailDomainException if the email's domain is on the blocklist
375	     */
376	    private static void validateEmailDomain(String email) {
377	        if (isBlank(email)) {
378	            return;
379	        }
380	        int at = email.lastIndexOf('@');
381	        if (at < 0) {
382	            return;
383	        }
384	        String domain = email.substring(at + 1).trim().toLowerCase(java.util.Locale.ROOT);
385	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
386	            throw new DisposableEmailDomainException(email);
387	        }
388	    }
389	
390	    /**
391	     * The fixed, region-keyed inclusive 4-digit postcode ranges. A region absent from this table
392	     * (locality {@code UNKNOWN}) imposes no range, so any 4-digit postcode is accepted there.
393	     */
394	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
395	        "NSW", new int[] {2000, 2099},
396	        "VIC", new int[] {3000, 3099},
397	        "QLD", new int[] {4000, 4099});
398	
399	    /**
400	     * Validates a supplied {@code postcode} against the owner's city region. Postcode is optional:
401	     * a {@code null} or blank value is accepted (validation only applies WHEN PRESENT). When
402	     * present, the value has already passed the 4-digit format check (Bean Validation on the
403	     * request body); this enforces that it falls within the inclusive range for the city's region
404	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region imposes no range.
405	     *
406	     * @param postcode the supplied postcode (may be {@code null})
407	     * @param region the owner's locality/region derived from its city
408	     * @throws InvalidPostcodeException if the postcode is out of range for the region
409	     */
410	    private static void validatePostcode(String postcode, String region) {
411	        if (isBlank(postcode)) {
412	            return;
413	        }
414	        int[] range = REGION_POSTCODES.get(region);
415	        if (range == null) {
416	            return;
417	        }
418	        int value;
419	        try {
420	            value = Integer.parseInt(postcode);
421	        }
422	        catch (NumberFormatException e) {
423	            throw new InvalidPostcodeException(postcode);
424	        }
425	        if (value < range[0] || value > range[1]) {
426	            throw new InvalidPostcodeException(postcode);
427	        }
428	    }
