430	    /**
431	     * Normalizes a street address into the canonical form stored on and returned for a newly
432	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
433	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
434	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
435	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
436	     * value is what gets persisted, echoed back, and used for every address comparison (household
437	     * duplicate detection and the shared household identifier).
438	     *
439	     * @param rawAddress the address value as supplied by the client
440	     * @return the normalized address (possibly empty, never {@code null})
441	     */
442	    private static String normalizeAddress(String rawAddress) {
443	        if (rawAddress == null) {
444	            return "";
445	        }
446	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
447	        if (collapsed.isEmpty()) {
448	            return "";
449	        }
450	        String[] tokens = collapsed.split(" ");
451	        StringBuilder sb = new StringBuilder(collapsed.length());
452	        for (int i = 0; i < tokens.length; i++) {
453	            String token = tokens[i];
454	            switch (token) {
455	                case "ST" -> token = "STREET";
456	                case "RD" -> token = "ROAD";
457	                case "AVE" -> token = "AVENUE";
458	                default -> { }
459	            }
460	            if (i > 0) {
461	                sb.append(' ');
462	            }
463	            sb.append(token);
464	        }
465	        return sb.toString();
466	    }
