468	    /**
469	     * Builds the customer code assigned to a newly created owner. The code is formatted
470	     * {@code <REGION>-<HASH8>} where {@code REGION} is the region derived from the owner's postcode
471	     * (see {@link Owner#getRegion()}) and {@code HASH8} is the first 8 upper-case hex characters of
472	     * the SHA-256 digest of the owner's normalized (E.164) telephone concatenated with its last
473	     * name (e.g. {@code NSW-1A2B3C4D}). No sequence number is involved, so the code depends only on
474	     * the owner's own region and identity.
475	     *
476	     * @param owner the owner being created, with telephone already normalized and postcode/city set
477	     * @return the customer code to assign
478	     */
479	    private static String customerCodeFor(Owner owner) {
480	        return owner.getRegion() + "-" + telephoneNameHash(owner.getTelephone(), owner.getLastName());
481	    }
482	
483	    /**
484	     * De-duplicates a freshly computed customer code against the codes already assigned to existing
485	     * owners. When no existing owner carries the given code it is returned unchanged; otherwise the
486	     * smallest suffix {@code -<n>} with {@code n >= 2} that yields a code no existing owner holds is
487	     * appended, guaranteeing distinct owners always receive distinct customer codes.
488	     *
489	     * @param customerCode the customer code computed for the owner being created
490	     * @return the de-duplicated customer code, unique among existing owners
491	     */
492	    private String deduplicateCustomerCode(String customerCode) {
493	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
494	            .map(Owner::getCustomerCode)
495	            .filter(java.util.Objects::nonNull)
496	            .collect(java.util.stream.Collectors.toSet());
497	        if (!existing.contains(customerCode)) {
498	            return customerCode;
499	        }
500	        int n = 2;
501	        while (existing.contains(customerCode + "-" + n)) {
502	            n++;
503	        }
504	        return customerCode + "-" + n;
505	    }
506	
507	    /**
508	     * Computes the {@code HASH8} segment of the customer code: the first 8 upper-case hex
509	     * characters of the SHA-256 digest of the normalized (E.164) telephone concatenated with the
510	     * last name.
511	     *
512	     * @param normalizedTelephone the owner's telephone in E.164 form
513	     * @param lastName the owner's last name
514	     * @return the 8-character upper-case hex hash
515	     */
516	    private static String telephoneNameHash(String normalizedTelephone, String lastName) {
517	        String key = (normalizedTelephone == null ? "" : normalizedTelephone)
518	            + (lastName == null ? "" : lastName);
519	        try {
520	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
521	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
522	            StringBuilder sb = new StringBuilder(digest.length * 2);
523	            for (byte b : digest) {
524	                sb.append(String.format("%02x", b));
525	            }
526	            return sb.substring(0, 8).toUpperCase(java.util.Locale.ROOT);
527	        }
528	        catch (java.security.NoSuchAlgorithmException e) {
529	            throw new IllegalStateException("SHA-256 not available", e);
530	        }
531	    }
532	
533	    /**
534	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
535	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
536	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
537	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits, and the length of
538	     * the national number must match the country code: {@code +61} requires 9 national digits and
539	     * {@code +1} requires 10.
540	     *
541	     * @param rawTelephone the telephone value as supplied by the client
542	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
543	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
544	     */
545	    private static String normalizeTelephone(String rawTelephone) {
546	        if (rawTelephone == null) {
547	            throw new InvalidTelephoneException(rawTelephone);
548	        }
549	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
550	        String e164;
551	        if (cleaned.startsWith("+")) {
552	            String digits = cleaned.substring(1);
553	            if (!digits.matches("[0-9]+")) {
554	                throw new InvalidTelephoneException(rawTelephone);
555	            }
556	            e164 = "+" + digits;
557	        } else {
558	            if (!cleaned.matches("[0-9]+")) {
559	                throw new InvalidTelephoneException(rawTelephone);
560	            }
561	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
562	            e164 = "+61" + national;
563	        }
564	        int digitCount = e164.length() - 1;
565	        if (digitCount < 8 || digitCount > 15) {
566	            throw new InvalidTelephoneException(rawTelephone);
567	        }
568	        if (e164.startsWith("+61")) {
569	            if (e164.length() - "+61".length() != 9) {
570	                throw new InvalidTelephoneException(rawTelephone);
571	            }
572	        }
573	        else if (e164.startsWith("+1")) {
574	            if (e164.length() - "+1".length() != 10) {
575	                throw new InvalidTelephoneException(rawTelephone);
576	            }
577	        }
578	        return e164;
579	    }
580	
581	    /**
582	     * Determines whether any existing owner already carries the given identity key. The identity key
583	     * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}) is the single value
584	     * all duplicate detection is based on, so two owners collide only when their whole identity keys
585	     * are equal.
586	     *
587	     * @param identityKey the identity key of the owner being created
588	     * @return {@code true} if another owner already has the same identity key
589	     */
590	    private boolean isIdentityKeyInUse(String identityKey) {
591	        return this.clinicService.findAllOwners().stream()
592	            .filter(existing -> !existing.isDeleted())
593	            .map(Owner::getIdentityKey)
594	            .anyMatch(identityKey::equals);
595	    }
596	
597	    /**
598	     * Finds an existing owner that the owner being created is a possible (soft) duplicate of: one
599	     * that shares the same last name (compared case-insensitively, whitespace-collapsed) and the
600	     * same postcode but carries a <em>different</em> telephone. Such a create is not rejected as a
601	     * hard duplicate, but is flagged. An owner with no postcode can never be a soft duplicate. When
602	     * several owners match, the earliest (lowest id) is returned so the result is deterministic.
603	     *
604	     * @param owner the owner being created (telephone already normalized, postcode set)
605	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
606	     */
607	    private Integer possibleDuplicateOf(Owner owner) {
608	        if (isBlank(owner.getPostcode())) {
609	            return null;
610	        }
611	        String normalizedLastName = normalizeIdentity(owner.getLastName());
612	        return this.clinicService.findAllOwners().stream()
613	            .filter(existing -> existing.getId() != null
614	                && !existing.isDeleted()
615	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
616	                && owner.getPostcode().equals(existing.getPostcode())
617	                && !java.util.Objects.equals(owner.getTelephone(), existing.getTelephone()))
618	            .map(Owner::getId)
619	            .min(Integer::compareTo)
620	            .orElse(null);
621	    }
622	
623	    /**
624	     * Counts how many existing owners already share the given first name and last name with the
625	     * owner being created. Both names are compared case-insensitively (after trimming and
626	     * collapsing runs of whitespace). The count reflects the state before the new owner is
627	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
628	     *
629	     * @param firstName the first name of the owner being created
630	     * @param lastName the last name of the owner being created
631	     * @return the number of existing owners sharing the same first and last name
632	     */
633	    private int namesakeCount(String firstName, String lastName) {
634	        String normalizedFirstName = normalizeIdentity(firstName);
635	        String normalizedLastName = normalizeIdentity(lastName);
636	        return (int) this.clinicService.findAllOwners().stream()
637	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
638	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
639	            .count();
640	    }
641	
642	    /**
643	     * Counts how many members the owner being created belongs to in its household, including
644	     * itself, as of this create. Members are the owners sharing the given {@code householdId};
645	     * the new owner is not yet persisted, so its own membership is added to the existing count.
646	     * An owner not assigned to a shared household ({@code householdId} is {@code null}) is a
647	     * household of one.
648	     *
649	     * @param householdId the shared household identifier assigned to the owner being created, or
650	     *                    {@code null} if the owner does not share a household
651	     * @return the number of household members after this create (at least 1)
652	     */
653	    private int householdSizeAfterCreate(String householdId) {
654	        if (householdId == null) {
655	            return 1;
656	        }
657	        long existing = this.clinicService.findAllOwners().stream()
658	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
659	            .count();
660	        return (int) existing + 1;
661	    }
662	
663	    /**
664	     * The maximum number of owners permitted in a single city. Once a city already contains this
665	     * many owners it is considered full and no further owners may be created there.
666	     */
667	    private static final int CITY_CAPACITY = 50;
668	
669	    /**
670	     * Determines whether the given city has already reached its capacity, i.e. already contains
671	     * {@value #CITY_CAPACITY} or more existing owners. Cities are compared case-insensitively after
672	     * collapsing runs of whitespace to a single space and trimming.
673	     *
674	     * @param city the city of the owner being created
675	     * @return {@code true} if the city already contains {@value #CITY_CAPACITY} or more owners
676	     */
677	    private boolean isCityAtCapacity(String city) {
678	        String normalizedCity = normalizeIdentity(city);
679	        long count = this.clinicService.findAllOwners().stream()
680	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
681	            .count();
682	        return count >= CITY_CAPACITY;
683	    }
684	
685	    /**
686	     * The maximum number of owners that may be created on any single day. Once this many owners
687	     * already carry a {@code registrationDate} of the current day, no further owners may be created
688	     * that day.
689	     */
690	    private static final int DAILY_REGISTRATION_LIMIT = 100;
691	
692	    /**
693	     * Determines whether the daily registration limit has already been reached, i.e. whether
694	     * {@value #DAILY_REGISTRATION_LIMIT} or more existing owners already carry the given date as
695	     * their {@code registrationDate}.
696	     *
697	     * @param date the current day
698	     * @return {@code true} if {@value #DAILY_REGISTRATION_LIMIT} or more owners were already
699	     *         registered on the given date
700	     */
701	    /**
702	     * The fixed public holidays that the business-day roll skips. A registration date landing on
703	     * any of these is rolled forward, exactly as it is for a weekend.
704	     */
705	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
706	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
707	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
708	        LocalDate.parse("2026-12-28"));
709	
710	    /**
711	     * Rolls a registration date forward onto a business day. A date that already falls on a
712	     * weekday which is not a public holiday is returned unchanged; a Saturday, Sunday or listed
713	     * public holiday is rolled forward, one day at a time, until the next non-weekend,
714	     * non-holiday day is reached. This adjusted date is what gets stored as the
715	     * {@code registrationDate} and drives everything derived from it (the fiscal year, the
716	     * membership number's fiscal-year segment, the daily create-limit).
717	     *
718	     * @param date the effective registration date (supplied by the client or defaulted to the
719	     *             server's current date)
720	     * @return the same date if it is a business day, otherwise the next business day that is
721	     *         neither a weekend nor a public holiday
722	     */
723	    private static LocalDate toBusinessDay(LocalDate date) {
724	        while (isNonBusinessDay(date)) {
725	            date = date.plusDays(1);
726	        }
727	        return date;
728	    }
729	
730	    private static boolean isNonBusinessDay(LocalDate date) {
731	        DayOfWeek dayOfWeek = date.getDayOfWeek();
732	        return dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY
733	            || PUBLIC_HOLIDAYS.contains(date);
734	    }
735	
736	    private boolean isDailyRegistrationLimitReached(LocalDate date) {
737	        long count = this.clinicService.findAllOwners().stream()
738	            .filter(existing -> date.equals(existing.getRegistrationDate()))
739	            .count();
740	        return count >= DAILY_REGISTRATION_LIMIT;
741	    }
742	
743	    /**
744	     * The number of owners that may be created on a single day before the bulk-signup warning is
745	     * raised. Once <em>more than</em> this many owners already carry the current business day as
746	     * their {@code registrationDate}, responses flag {@code bulkSignupWarning} true.
747	     */
748	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
749	
750	    /**
751	     * Determines whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
752	     * created today, i.e. already carry the current business day as their {@code registrationDate}.
753	     * This shares the daily create-limit's accumulation path (owners counted by registration date).
754	     *
755	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners are already
756	     *         registered on today's business day
757	     */
758	    private boolean isBulkSignupWarning() {
759	        LocalDate today = toBusinessDay(LocalDate.now());
760	        long count = this.clinicService.findAllOwners().stream()
761	            .filter(existing -> today.equals(existing.getRegistrationDate()))
762	            .count();
763	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
764	    }
765	
766	    /**
767	     * Computes the membership level to assign to the owner being created, applying the household
768	     * level ceiling: a new owner's level may not exceed one above the current maximum membership
769	     * level among their existing household members. The owner's own naturally derived level (see
770	     * {@link Owner#getComputedMembershipLevel()}) is returned unchanged when there is no existing
771	     * household member; otherwise it is capped at {@code maxHouseholdLevel + 1}. Existing members are
772	     * the non-deleted owners already sharing the owner's {@code householdId}; the owner being created
773	     * is not yet persisted, so it is naturally excluded.
774	     *
775	     * @param owner the owner being created, with {@code householdId} and the fields driving its
776	     *              membership level already set
777	     * @return the (possibly capped) membership level to store on the owner
778	     */
779	    private int cappedMembershipLevel(Owner owner) {
780	        int naturalLevel = owner.getComputedMembershipLevel();
781	        String householdId = owner.getHouseholdId();
782	        if (householdId == null) {
783	            return naturalLevel;
784	        }
785	        java.util.OptionalInt maxHouseholdLevel = this.clinicService.findAllOwners().stream()
786	            .filter(existing -> existing.getId() != null
787	                && !existing.isDeleted()
788	                && householdId.equals(existing.getHouseholdId()))
789	            .mapToInt(Owner::getMembershipLevel)
790	            .max();
791	        if (maxHouseholdLevel.isEmpty()) {
792	            return naturalLevel;
793	        }
794	        return Math.min(naturalLevel, maxHouseholdLevel.getAsInt() + 1);
795	    }
796	
797	    /**
798	     * Derives the stable household identifier for a given last name and postcode. The value is the
799	     * first 12 upper-case hex characters of the SHA-256 digest of {@code normalizedLastName + '|' +
800	     * postcode}, so it is deterministic across calls and identical for every owner sharing the same
801	     * normalized last name and postcode — they belong to the same household automatically.
802	     *
803	     * @param lastName the last name of the household
804	     * @param postcode the postcode of the household (may be {@code null})
805	     * @return the deterministic household identifier
806	     */
807	    private static String householdIdFor(String lastName, String postcode) {
808	        String key = normalizeIdentity(lastName) + "|" + (postcode == null ? "" : postcode);
809	        try {
810	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
811	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
812	            StringBuilder sb = new StringBuilder(digest.length * 2);
813	            for (byte b : digest) {
814	                sb.append(String.format("%02x", b));
815	            }
816	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
817	        }
818	        catch (java.security.NoSuchAlgorithmException e) {
819	            throw new IllegalStateException("SHA-256 not available", e);
820	        }
821	    }
822	
823	    /**
824	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
825	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
826	     * single space, and the result is lower-cased.
827	     *
828	     * @param value the raw field value
829	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
830	     */
831	    private static String normalizeIdentity(String value) {
832	        if (value == null) {
833	            return "";
834	        }
835	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
836	    }
837	}
