165	    /**
166	     * Stores the email lower-cased so it is persisted and returned in a canonical form. A
167	     * {@code null} value (email omitted) is preserved as {@code null}.
168	     */
169	    public void setEmail(String email) {
170	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
171	    }
172	
173	    public LocalDate getRegistrationDate() {
174	        return this.registrationDate;
175	    }
