189	    /**
190	     * The owner's age band, derived from {@link #birthDate} measured against the
191	     * {@link #registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64
192	     * inclusive, and {@code SENIOR} at 65 or over. Returns {@code null} when no birth date was
193	     * supplied, so the field is simply absent from the response.
194	     */
195	    @Transient
196	    public String getAgeBand() {
197	        if (this.birthDate == null) {
198	            return null;
199	        }
200	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
201	        int age = java.time.Period.between(this.birthDate, reference).getYears();
202	        if (age < 18) {
203	            return "MINOR";
204	        }
205	        if (age < 65) {
206	            return "ADULT";
207	        }
208	        return "SENIOR";
209	    }
