211	    /** National-number length by country code, mirroring the create-time E.164 normalization. */
212	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of("61", 9, "1", 10);
213	
214	    /**
215	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
216	     * national digits grouped in threes from the left (e.g. {@code +61412345678 -> +61 412 345 678}).
217	     * The country code is recognised from the known set ({@code +61} with 9 national digits, {@code +1}
218	     * with 10) that the create-time normalization produces. Values that are absent or not in E.164 form
219	     * are returned unchanged, so the raw {@link #telephone} still stands in for a display value.
220	     */
221	    @Transient
222	    public String getTelephoneDisplay() {
223	        if (this.telephone == null || !this.telephone.startsWith("+")) {
224	            return this.telephone;
225	        }
226	        String digits = this.telephone.substring(1);
227	        if (!digits.matches("[0-9]+")) {
228	            return this.telephone;
229	        }
230	        String countryCode = null;
231	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
232	            if (digits.startsWith(entry.getKey())
233	                && digits.length() - entry.getKey().length() == entry.getValue()) {
234	                countryCode = entry.getKey();
235	                break;
236	            }
237	        }
238	        if (countryCode == null) {
239	            return this.telephone;
240	        }
241	        String national = digits.substring(countryCode.length());
242	        StringBuilder grouped = new StringBuilder();
243	        for (int i = 0; i < national.length(); i += 3) {
244	            if (grouped.length() > 0) {
245	                grouped.append(' ');
246	            }
247	            grouped.append(national, i, Math.min(i + 3, national.length()));
248	        }
249	        return "+" + countryCode + " " + grouped;
250	    }
