252	    public String getCustomerCode() {
253	        return this.customerCode;
254	    }
255	
256	    public void setCustomerCode(String customerCode) {
257	        this.customerCode = customerCode;
258	    }
259	
260	    /**
261	     * A single Luhn check digit (0-9) computed over the digits contained in the
262	     * {@link #customerCode}. Non-digit characters in the code are ignored; the standard Luhn
263	     * algorithm doubles every second digit from the right (subtracting 9 when the result exceeds
264	     * 9) and the check digit is {@code (10 - (sum % 10)) % 10}. {@code null} until a customer code
265	     * is assigned.
266	     */
267	    @Transient
268	    public Integer getCheckDigit() {
269	        if (this.customerCode == null) {
270	            return null;
271	        }
272	        int sum = 0;
273	        boolean dbl = true;
274	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
275	            char c = this.customerCode.charAt(i);
276	            if (c < '0' || c > '9') {
277	                continue;
278	            }
279	            int d = c - '0';
280	            if (dbl) {
281	                d *= 2;
282	                if (d > 9) {
283	                    d -= 9;
284	                }
285	            }
286	            sum += d;
287	            dbl = !dbl;
288	        }
289	        return (10 - (sum % 10)) % 10;
290	    }
291	
292	    /** The month on which the fiscal year starts: 1 July. */
293	    private static final java.time.Month FISCAL_YEAR_START_MONTH = java.time.Month.JULY;
294	
295	    /**
296	     * The calendar year in which the fiscal year containing {@code date} began. The fiscal year
297	     * starts on 1 July, so a date in July through December belongs to a fiscal year that began in
298	     * its own calendar year, while a date in January through June belongs to one that began in the
299	     * previous calendar year.
300	     */
301	    private static int fiscalYearStart(LocalDate date) {
302	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH.getValue() ? date.getYear() : date.getYear() - 1;
303	    }
304	
305	    /**
306	     * The owner's fiscal year, formatted {@code FY<YY>} where {@code YY} is the last two digits of
307	     * the calendar year in which the fiscal year containing the {@code registrationDate} began (the
308	     * fiscal year starts on 1 July; e.g. a registration on 2026-08-11 yields {@code FY26}). Derived
309	     * from the (business-day-adjusted) {@code registrationDate}; {@code null} until it is assigned.
310	     */
311	    @Transient
312	    public String getFiscalYear() {
313	        if (this.registrationDate == null) {
314	            return null;
315	        }
316	        return String.format("FY%02d", fiscalYearStart(this.registrationDate) % 100);
317	    }
318	
319	    /**
320	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where {@code YY} is
321	     * the last two digits of the fiscal year of the {@code registrationDate} (the fiscal year
322	     * starts on 1 July; e.g. {@code NSW-1A2B3C4D-M26}). Derived from the owner's own fields;
323	     * {@code null} until both are assigned.
324	     */
325	    @Transient
326	    public String getMembershipNumber() {
327	        if (this.customerCode == null || this.registrationDate == null) {
328	            return null;
329	        }
330	        return String.format("%s-M%02d", this.customerCode, fiscalYearStart(this.registrationDate) % 100);
331	    }
332	
333	    /**
334	     * The owner's membership points, derived from the owner's own fields. Points start at 0 and
335	     * accumulate: 2 when an email is present, 1 when the owner has no namesakes ({@code namesakeCount}
336	     * is 0), 2 when the owner belongs to a household of 3 or more members ({@code householdSize} is at
337	     * least 3), and 3 when the owner's tenure — the number of elapsed fiscal years from
338	     * {@link #registrationDate} to today, the fiscal year starting on 1 July — exceeds one. Because
339	     * a newly created owner registers in the current fiscal year and so has zero tenure, and joins a
340	     * household of at most itself unless others already share it, a new owner's points reflect only the
341	     * factors captured at creation time.
342	     */
343	    @Transient
344	    public Integer getMembershipPoints() {
345	        int points = 0;
346	        boolean hasEmail = this.email != null && !this.email.isBlank();
347	        if (hasEmail) {
348	            points += 2;
349	        }
350	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
351	        if (noNamesakes) {
352	            points += 1;
353	        }
354	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
355	        if (largeHousehold) {
356	            points += 2;
357	        }
358	        boolean longTenure = this.registrationDate != null
359	            && (fiscalYearStart(LocalDate.now()) - fiscalYearStart(this.registrationDate)) > 1;
360	        if (longTenure) {
361	            points += 3;
362	        }
363	        return points;
364	    }
365	
366	    /**
367	     * The owner's membership level, a number from 1 to 4. Ordinarily it is the level derived from
368	     * {@link #getMembershipPoints()} (level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5
369	     * points, and level 4 for 6 or more points). When an explicit level has been assigned at creation
370	     * time — because it was capped to at most one above the maximum level among the owner's existing
371	     * household members — that stored value is returned instead.
372	     */
373	    public Integer getMembershipLevel() {
374	        if (this.membershipLevel != null) {
375	            return this.membershipLevel;
376	        }
377	        return getComputedMembershipLevel();
378	    }
379	
380	    public void setMembershipLevel(Integer membershipLevel) {
381	        this.membershipLevel = membershipLevel;
382	    }
383	
384	    /**
385	     * The membership level derived purely from {@link #getMembershipPoints()} (before any
386	     * household level ceiling is applied): level 1 for 0-1 points, level 2 for 2-3 points, level 3
387	     * for 4-5 points, and level 4 for 6 or more points.
388	     */
389	    @Transient
390	    public Integer getComputedMembershipLevel() {
391	        int points = getMembershipPoints();
392	        if (points <= 1) {
393	            return 1;
394	        }
395	        if (points <= 3) {
396	            return 2;
397	        }
398	        if (points <= 5) {
399	            return 3;
400	        }
401	        return 4;
402	    }
