404	    /** City -> canonical region for the {@code region} derivation. */
405	    private static final Map<String, String> CITY_REGION = Map.of(
406	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
407	
408	    /** Region -> inclusive 4-digit postcode range {low, high} for the {@code region} derivation. */
409	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
410	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
411	
412	    /** Region -> IANA timezone for the {@code timezone} derivation. */
413	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
414	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
415	
416	    /**
417	     * The region code that forms the {@code REGION} segment of the {@link #customerCode}, derived
418	     * by looking up the region by {@link #postcode} range first (NSW 2000-2099, VIC 3000-3099,
419	     * QLD 4000-4099), and only falling back to the fixed city-to-region table (Sydney->NSW,
420	     * Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no known range. Returns
421	     * {@code UNKNOWN} when neither source resolves a region.
422	     */
423	    @Transient
424	    public String getRegion() {
425	        String region = regionForPostcode(this.postcode);
426	        if (region != null) {
427	            return region;
428	        }
429	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
430	    }
431	
432	    /**
433	     * The owner's locality: the {@code REGION} segment of its {@link #customerCode} (everything
434	     * before the first {@code '-'}). Because the customer code is {@code <REGION>-<HASH8>} with
435	     * {@code REGION} derived from the postcode, the locality now simply reads that region back off
436	     * the identity. Returns {@code UNKNOWN} until a customer code is assigned.
437	     */
438	    @Transient
439	    public String getLocality() {
440	        if (this.customerCode == null) {
441	            return "UNKNOWN";
442	        }
443	        int dash = this.customerCode.indexOf('-');
444	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
445	    }
446	
447	    /**
448	     * The owner's timezone as an IANA name, derived from its {@link #getLocality() locality} (the
449	     * region) via the fixed region-to-timezone table: {@code NSW->Australia/Sydney},
450	     * {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}. Returns {@code null} when
451	     * the locality is not one of those regions.
452	     */
453	    @Transient
454	    public String getTimezone() {
455	        return REGION_TIMEZONE.get(getLocality());
456	    }
457	
458	    /** Region whose postcode range contains the given postcode, or {@code null} when none does. */
459	    private static String regionForPostcode(String postcode) {
460	        if (postcode == null) {
461	            return null;
462	        }
463	        int value;
464	        try {
465	            value = Integer.parseInt(postcode.trim());
466	        }
467	        catch (NumberFormatException ex) {
468	            return null;
469	        }
470	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
471	            int[] range = entry.getValue();
472	            if (value >= range[0] && value <= range[1]) {
473	                return entry.getKey();
474	            }
475	        }
476	        return null;
477	    }
478	
479	    /**
480	     * The owner's identity key, the single derived value all duplicate detection is based on. It is
481	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone
482	     * is the stored E.164 value, the email is the stored lower-cased value (empty when absent) and
483	     * the household segment is the deterministic {@code householdId} derived from the last name and
484	     * postcode (empty only when no household id has been assigned). Two owners are duplicates only
485	     * when their whole identity keys are equal.
486	     */
487	    @Transient
488	    public String getIdentityKey() {
489	        String telephonePart = this.telephone == null ? "" : this.telephone;
490	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
491	        String householdPart = this.householdId == null ? "" : this.householdId;
492	        return telephonePart + "|" + emailPart + "|" + householdPart;
493	    }
494	
495	    public String getHouseholdId() {
496	        return this.householdId;
497	    }
498	
499	    public void setHouseholdId(String householdId) {
500	        this.householdId = householdId;
501	    }
502	
503	    public Integer getNamesakeCount() {
504	        return this.namesakeCount;
505	    }
506	
507	    public void setNamesakeCount(Integer namesakeCount) {
508	        this.namesakeCount = namesakeCount;
509	    }
510	
511	    public Integer getHouseholdSize() {
512	        return this.householdSize;
513	    }
514	
515	    public void setHouseholdSize(Integer householdSize) {
516	        this.householdSize = householdSize;
517	    }
518	
519	    public String getPostcode() {
520	        return this.postcode;
521	    }
522	
523	    public void setPostcode(String postcode) {
524	        this.postcode = postcode;
525	    }
526	
527	    public Boolean getPossibleDuplicate() {
528	        return this.possibleDuplicate;
529	    }
530	
531	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
532	        this.possibleDuplicate = possibleDuplicate;
533	    }
534	
535	    public Integer getPossibleDuplicateOf() {
536	        return this.possibleDuplicateOf;
537	    }
538	
539	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
540	        this.possibleDuplicateOf = possibleDuplicateOf;
541	    }
542	
543	    /**
544	     * Whether this owner has been soft-deleted. A newly created owner is not deleted; a
545	     * {@code DELETE /api/owners/{id}} marks the owner deleted (setting this true) while retaining the
546	     * row, and duplicate/identity detection ignores owners flagged deleted.
547	     */
548	    public boolean isDeleted() {
549	        return this.deleted;
550	    }
551	
552	    public void setDeleted(boolean deleted) {
553	        this.deleted = deleted;
554	    }
555	
556	    protected Set<Pet> getPetsInternal() {
557	        if (this.pets == null) {
558	            this.pets = new HashSet<>();
559	        }
560	        return this.pets;
561	    }
562	
563	    protected void setPetsInternal(Set<Pet> pets) {
564	        this.pets = pets;
565	    }
566	
567	    public List<Pet> getPets() {
568	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
569	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
570	        return Collections.unmodifiableList(sortedPets);
571	    }
572	
573	    public void setPets(List<Pet> pets) {
574	        this.pets = new HashSet<>(pets);
575	    }
576	
577	    public void addPet(Pet pet) {
578	        getPetsInternal().add(pet);
579	        pet.setOwner(this);
580	    }
581	
582	    /**
583	     * Return the Pet with the given name, or null if none found for this Owner.
584	     *
585	     * @param name to test
586	     * @return true if pet name is already in use
587	     */
588	    public Pet getPet(String name) {
589	        return getPet(name, false);
590	    }
591	
592	    /**
593	     * Return the Pet with the given name, or null if none found for this Owner.
594	     *
595	     * @param name to test
596	     * @return true if pet name is already in use
597	     */
598	    public Pet getPet(String name, boolean ignoreNew) {
599	        name = name.toLowerCase();
600	        for (Pet pet : getPetsInternal()) {
601	            if (!ignoreNew || !pet.isNew()) {
602	                String compName = pet.getName();
603	                compName = compName.toLowerCase();
604	                if (compName.equals(name)) {
605	                    return pet;
606	                }
607	            }
608	        }
609	        return null;
610	    }
611	
612	    public Pet getPet(Integer petId) {
613	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
614	    }
615	
616	    @Override
617	    public String toString() {
618	        return new ToStringCreator(this)
619	
620	            .append("id", this.getId())
621	            .append("new", this.isNew())
622	            .append("lastName", this.getLastName())
623	            .append("firstName", this.getFirstName())
624	            .append("address", this.address)
625	            .append("city", this.city)
626	            .append("telephone", this.telephone)
627	            .append("email", this.email)
628	            .toString();
629	    }
630	}
